def render_html(data,svg=None,csv_text=None):
    validate(data);svg=svg or render_svg(data);csv_text=csv_text or render_csv(data);page=PAGE
    opts=lambda values:''.join(f'<option value="{esc(v)}">{esc(v.replace("_"," "))}</option>' for v in values)
    rep={'__TITLE__':esc(data['title']),'__EYEBROW__':esc(data['presentation']['eyebrow']),'__HEADLINE__':esc(data['presentation']['headline']),'__LEDE__':esc(data['presentation']['lede']),'__STATUS_OPTIONS__':opts(STATUSES),'__CONF_OPTIONS__':opts(CONFIDENCE),'__TYPE_OPTIONS__':opts(TYPES),'__STRATEGY_OPTIONS__':opts(STRATEGIES),'__OWNERSHIP_OPTIONS__':opts(OWNERSHIP),'__MAX__':str(data['scale']['max_rating']),'__BOUNDARY__':esc(data['decision_boundary']),'__METHOD__':esc(data['analysis']['method']),'__SCORING__':esc(data['analysis']['scoring_boundary']),'__AUTH__':esc(data['analysis']['authority_boundary']),'__REVIEW__':esc(data['analysis']['review_rule']),'__DATA__':_json(data),'__CSV__':_json(csv_text),'__SVG__':_json(uri(svg,'image/svg+xml'))}
    for k,v in rep.items():page=page.replace(k,v)
    return page

